insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place)
values
(E'https://matcha-jp.com/ko/7360', E'ko', 37, E'【가가와】 일본 최고의 일몰 명소! 세토나이카이 ・ 치치부가하마의 다섯 가지 즐기는 법', E'카가와현 서부의 미토요시에 있는 치치부가하마는 일본 최고의 석양을 즐길 수 있는 절경 명소로 유명합니다. 하지만 여기에 있는 것은 절경 뿐만 아닙니다. 카약이 있는 명소와 현지 음식을 즐길 수 있는 카페, 멋진 게스트 하우스와 기념품 가게도 있습니다!\n\nPicture coutesy of 三豊市(미토요시) 카가와현 서부의 미토요시에 있는父母ヶ浜(치치부가하마)는 2016년 이후 SNS를 통해 인기를 끌고 있는 절경 명소. 특히 저녁은에는 아름다운 경관을 볼 수 있어서 일본의 주요 여행 잡지에서 2018년에 ‘가고 싶은 석양 절경 랭킹’ 1위를 차지했습니다.\n\n이 절경의 비밀은 썰물 때 모래 사장에 있는 조수 웅덩이에 있습니다. 바람이 약한 날은 조수 웅덩이의 물이 거울과 같아서 하늘을 아름답게 비추고 있습니다.\n\n조수 웅덩이는 바위에 있는 경우가 많는데, 치치부가하마에서는 모래 사장에 큰 조수 웅덩이가 있습니다. 이러한 특수성이 기적의 절경을 만들어 내고 있는 것입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76985.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76989.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76986.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76987.webp"]'::jsonb, E'2019-06-19'::timestamptz, E'미토요시'),
(E'https://matcha-jp.com/ko/27000', E'ko', 37, E'[일본 여행] 나오시마 예술 현장을 둘러보는 1일 가이드 투어', E'이 가이드는 나오시마의 주요 예술 명소를 효율적으로 방문하는 방법을 소개합니다. 박물관과 작품을 감상하고 그 배경에 대한 설명을 들을 수 있는 투어의 매력을 강조하며, 교통편과 여행 준비를 포함한 모든 걱정 없는 여행을 보장합니다.\n\n나오시마를 제대로 즐기시려면 "트립 투 재팬"의 가이드 투어를 추천합니다.\n\n이곳은 단순히 예술 작품을 감상하는 장소가 아니라, 이해와 탐구의 여정입니다.\n\n이 투어의 ​​가장 큰 매력은 전문 지식을 갖춘 가이드가 동행한다는 점입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261802.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261803.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261804.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/30-261805.webp"]'::jsonb, E'2026-03-30'::timestamptz, E'나오시마'),
(E'https://matcha-jp.com/ko/3768', E'ko', 38, E'작품의 배경이 된 곳부터 봇짱 극장까지. 에히메현 마츠야마시의 봇짱 관련 시설을 소개합니다!!', E'일본의 근대문학의 기초를 다진 문호・나쓰메 소세키. 그 대표작인 『도련님(坊ちゃん/봇짱)』은, 나쓰메 소세키가 마쓰야마 중학교에 1년간 부임했을 당시의 체험을 바탕으로 그린 이야기입니다. 그렇기 때문에 작품 안에는 당시 마쓰야마에 실존하고 있던 장소들이 등장하는데요. 이번 기사에서는 Google 스트리트뷰로, 마쓰야마 시내에 있는 “봇짱(坊ちゃん)” 관련 장소들을 소개합니다.\n\n일본을 대표하는 문호・나츠메 소세키(夏目漱石). 일본의 근대 문학의 기초를 다진 인물로, 옛 천엔 지폐에도 얼굴이 새겨졌던 것으로 유명합니다.\n\n그런 나츠메 소세키의 대표작이라 하면 『도련님(坊っちゃん/이하, 봇짱』을 꼽을 수 있지요.\n\n주인공인 도련님(봇짱)을 시작으로 거센바람, 마돈나, 끝물 호박, 빨간 셔츠, 알랑쇠 등 유니크한 등장인물이 인상적인 작품으로, 메이지 시대의 일본의 풍속을 알기에도 귀중한 소설입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/23-12355.webp"]'::jsonb, E'2017-01-18'::timestamptz, null),
(E'https://matcha-jp.com/ko/22343', E'ko', 38, E'시코쿠 추천 온천지 7선! 여유롭게 지낼 수 있는 숨은 명소와 온천 료칸도 소개!', E'시코쿠에서 추천하는 온천지와 온천 숙박 시설을 정리해서 소개합니다. 자연이 풍부한 시코쿠에는 바다와 산의 절경을 즐길 수 있는 온천지가 많습니다. 유명한 도고 온천과 시코쿠 최남단의 아시즈리 에 위치한 아시즈리 온천, 세토 내해에 있는 쇼도시마 온천 등 인기 있는 온천지를 확인해 봅시다.\n\n자연이 풍부한 시코쿠에는 산과 강, 바다의 절경을 즐기며 목욕할 수 있는 온천이 많이 있습니다. 오래된 역사와 옛 전설이 남아있는 온천도 있기 때문에 역사를 좋아하는 사람에게도 추천합니다.\n\n이번 기사에서는 시코쿠에서 유명한 온천이나 화제의 온천 등을 정리해 소개해 드리겠습니다.\n\n▼시코쿠에서 인기 있는 온천은 어디? 당일치기로 즐길 수 있는 온천 7선', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205443.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205895.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205445.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205447.webp"]'::jsonb, E'2024-12-30'::timestamptz, E'도고 온천'),
(E'https://matcha-jp.com/ko/10730', E'ko', 38, E'《센과 치히로의 행방불명》 의 모델! 도고 온천 본관의 불가사의한 공기에 젖어들다', E'에히메현 마츠야마시에 있는 도고 온천은 일본에서 가장 오래되었다고 알려진 유명한 온천장. 이곳에 서린 독특한 분위기가 수백 년 동안 변함없이 사람들을 매료시키고 있는 것 같습니다. 첫 시코쿠 여행으로 도고 온천을 탐방해 보았습니다.\n\n시코쿠를 대표하는 명탕이라고 하면 에히메현의 도고 온천을 떠올릴 수 있습니다. 일본 신화에도 등장하며 일본 삼고탕(三古湯)(※1) 중 하나로도 알려져 있습니다.\n\n도쿄에 거주하는 포토그래퍼인 필자는 이번에 도고 온천에서 가장 유명한 \'도고 온천 본관\'을 방문했습니다. 필자에게 있어서는 첫 시코쿠 여행이라서 더 기대에 부풀었습니다.\n\n※1: 일본삼고탕 - 일본에서 오랜 역사를 간직한 온천입니다. 아리마 온천(효고현), 도고 온천(에히메현), 시라하마 온천(와카야마현)의 3탕을 말함.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120321.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120322.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120323.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/12-120324.webp"]'::jsonb, E'2021-10-09'::timestamptz, E'도고 온천'),
(E'https://matcha-jp.com/ko/1442', E'ko', 39, E'코치 「이노쵸 종이 박물관」에서 오리지널 화지 만들기를 체험해보자!', E'일본의 시코쿠 지방 남부에 위치하는 <strong>코치현(高知県)</strong>. 태평양을 마주하고 있는 현으로, 조금 남쪽으로 가면 아름다운 바다를 볼 수 있어요. 바다야 산 등의 자연이 풍부하여, 신선한 생선이 잡히고, 맛있는 일본주가 만들어지고 있는, 관광지로써의 매력이 가득한 현 인데요, 아직 해외의 분들에게는 알려져 있지 않은 편이예요. 게다가, 다양한 체험형 활동이 있는 것도 코치현의 매력중 하나랍니다. 이번 기사에서는 그런 코치현의 체\n\n일본의 시코쿠 지방 남부에 위치하는 코치현(高知県). 태평양을 마주하고 있는 현으로, 조금 남쪽으로 가면 아름다운 바다를 볼 수 있어요.\n\n바다야 산 등의 자연이 풍부하여, 신선한 생선이 잡히고, 맛있는 일본주가 만들어지고 있는, 관광지로써의 매력이 가득한 현 인데요, 아직 해외의 분들에게는 알려져 있지 않은 편이예요.\n\n게다가, 다양한 체험형 활동이 있는 것도 코치현의 매력중 하나랍니다. 이번 기사에서는 그런 코치현의 체험 서비스를 소개 해 드릴게요.', E'["https://resources.matcha-jp.com/archive_files/jp/2015/11/ino20151120a_2.webp","https://resources.matcha-jp.com/archive_files/jp/2015/11/ino20151120l_2.webp","https://resources.matcha-jp.com/archive_files/jp/2015/11/ino20151120c_2.webp","https://resources.matcha-jp.com/archive_files/jp/2015/11/ino20151120d_2.webp"]'::jsonb, E'2017-01-30'::timestamptz, E'치시'),
(E'https://matcha-jp.com/ko/6301', E'ko', 40, E'라멘만 5천 그릇 먹어본 \'라멘덕후\'가 추천! 후쿠오카현・하카타 주변 인기 라멘 맛집 8곳', E'통산 5천 그릇 이상의 라멘을 먹어본 필자가 후쿠카현・하카타의 추천 라멘집을 소개합니다. 이 기사에서는 하카타 명물인 돈코츠라멘뿐만 아니라 하카타에서도 즐길수있는 돈코츠 이외의 라멘에 대해서도 소개합니다. 하카타의 라멘정보라면, MATCHA!\n\n후쿠오카현・하카타라 하면, 뽀얀 국물의 돈코츠라멘을 떠올리시는 분들이 많을텐데요.\n\n물론, 하카타에서는 아직 돈코츠라멘이 주류지만 최근에는 또 다른 형태의 라멘도 쉽게 맛볼 수 있게 되었습니다. 이번 기사에서는 돈코츠라멘과 함께 하카타에서 최근 만나볼 수 있는 돈코츠 이외의 라멘도 소개할게요.\n\n하카타라 하면, 역시 돈코츠라멘이 유명해요. 그 중에서 가장 인기 많은 곳이 바로 이「하카타잇소 하카타역히가시본점 」입니다. 라멘은 돈코츠라멘 한 종류뿐 으로 그 외에는 토핑과 사이드메뉴만 제공하는 심플한 메뉴구성! (사진의「라멘」은 세금포함 650円).', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/09-58093.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58103.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58104.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58105.webp"]'::jsonb, E'2019-05-30'::timestamptz, null),
(E'https://matcha-jp.com/ko/6122', E'ko', 40, E'키타 큐슈를 방문하면 무조건 해야 할 8가지', E'교통의 요충지로서 발전해 온 키타 큐슈 지역. 예로부터 제조업이 번성했던 곳으로, 당시의 모습이 남아있는 근대 건축물도 많아, 조금 걸음을 늦추면 자연미가 풍부한 장소도. 큐슈에 거주중인 필자가 키타큐슈 지역에서 꼭 가고 싶은 장소, 하고 싶은 일을 8개 엄선해 소개합니다\n\n관문 해협을 두고 혼슈와 접하고, 한반도와 중국에서 가깝다는 지리적 특성으로 교통의 요충지로서 발전해 온키타 큐슈시.\n\n예로부터 제조업이 번성한 곳으로, 당시의 모습을 남긴근대 건축물도 많이 남아 있습니다. 조금 더 발걸음을 옮기면자연미가 넘치는 곳도 있습니다.\n\n이번 기사에서는규슈에 거주하는 필자가, 다양한 매력이 가득 찬 키타 큐슈 지역에서무조건 가고 싶은 곳, 하고 싶은 것를 8개 엄선하여 소개합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/05/22-54477.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/22-54478.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/22-54479.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/22-54480.webp"]'::jsonb, E'2020-02-08'::timestamptz, null),
(E'https://matcha-jp.com/ko/2624', E'ko', 40, E'【2023】후쿠오카시・하카타의 추천 관광 명소 12선 & 맛집', E'후쿠오카는 도쿄에서 비행기로 두 시간, 신칸센을 타면 다섯 시간 정도면 갈 수 있는 곳이에요. 다자이후 텐만구, 나카스의 야타이, 캐널 시티 하카타, 오오호리 공원, 시가 섬 등, 음식과 따듯한 기후과 매력적인 후쿠오카 관광 스폿을 소개해 드릴게요!\n\n후쿠오카현은 \'규슈 지방\'에서 가장 큰 현입니다. 그 중심 도시인 후쿠오카시는 규슈 여행의 허브 역할을 하는 대도시입니다.\n\n나카가와 강 서쪽은 \'후쿠오카\', 나카가와 강 동쪽은 \'하카타\'라고 불린다. 하카타 라멘, 모츠나베 등 인기 있는 현지 음식이 있고, 쇼핑 명소도 많으며, \'우미노나카미치 해변공원\'과 같은 아름다운 경승지도 있습니다.\n\n최근에는 \'마린월드 우미노나카미치\'와 \'건담파크 후쿠오카\' 등 엔터테인먼트 시설도 많이 생겼습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/12/30-133403.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/02-122042.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/1546.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/10-122517.webp"]'::jsonb, E'2016-10-20'::timestamptz, E'다자이후'),
(E'https://matcha-jp.com/ko/10410', E'ko', 41, E'애주가에게 추천! 「가시마 우레시노 양조장(鹿島嬉野酒蔵) 투어」에서 규슈가 자랑하는 사케 문화를 체험하자!', E'일본 규슈 지방에 있는 사가현 가시마시, 우레시노시는 식도락가에 있어서 체험하지 않아서는 안 될 술과 음식 문화가 있습니다. 본 기사에서는 맛있는 술과 그 문화의 발견이 가득한 이틀간의 양조장 투어를 소개합니다.\n\n큐슈 지방에 있는 사가현가시마(鹿島)시에서는 대대로 일본주 제조가 성행해 왔습니다\n\n가시마의 양조장은 대부분 200 년 이상이나 되는 역사를 가지고 있으며, 몇몇 양조장은 관광객에게도 열려 있습니다. 그래서 섬세한 맛을 지닌 사케를 알고 즐기기에 가장 좋은 장소입니다.\n\n2일에 걸친 가고시마 우레시노 양조장 투어에서는에도 시대의 거리를 걸으며, 다양한 술과 지역의 맛있는 음식을 맛보고, 나아가 술 빚기도 즐길 수 있습니다!', E'["https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112555.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/24-112578.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112537.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112538.webp"]'::jsonb, E'2021-03-04'::timestamptz, E'우레시노시'),
(E'https://matcha-jp.com/ko/9568', E'ko', 40, E'후쿠오카의 추천 쇼핑 명소・아울렛 총정리', E'후쿠오카는 맛있는 음식 외에도 쇼핑을 즐길 수 있는 도시입니다. 이번 기사에서는 후쿠오카 거주 경험이 있는 필자가 THE OUTLETS KITAKYUSHU를 비롯한 아울렛 몰 외에 백화점, 쇼핑몰 등 여러 쇼핑 명소를 소개합니다.\n\n규슈의 현관・중심부까지 지하철로 5분이면 갈 수 있는 후쿠오카시는 최근 인기가 많아지고 있습니다. 그 ㅣㅇ유는 바로 맛집은 물론 쇼핑 하기에도 편리한 도시이기 때문입니다!\n\n이번 기사에서는 후쿠오카시 중심부, 그리고 후쿠오카현 내에 있는 아울렛 몰과 쇼핑몰을 엄선하여 소개합니다. 이 기사를 읽으시면 후쿠오카에서의 쇼핑을 완벽히 이해하실 수 있을 겁니다.\n\n후쿠오카현, 또 그 인근 지역에는 THE OUTLETS KITAKYUSHU, 도스(鳥栖) 프리미엄 아울렛까지 3개의 아울렛 몰이 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127833.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127837.webp","https://resources.matcha-jp.com/resize/720x2000/2023/04/19-137288.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99807.webp"]'::jsonb, E'2022-11-08'::timestamptz, E'후쿠오카시'),
(E'https://matcha-jp.com/ko/21465', E'ko', 40, E'규슈 각 지역의 날씨 특징 완벽 분석! 계절에 맞는 복장, 행사 소개', E'온난하다고 알려진 규슈의 기후를 현별로 소개합니다. 규슈는 남북으로 길기 때문에 지역에 따라 기후가 달라집니다. 지역별 기후의 특징 외에도 평균 기온과 습도 데이터를 월별로 정리했습니다. 이 외에 계절별로 어울리는 복장이나 많은 사람들로 붐비는 행사 정보도 실어두었습니다.\n\n규슈 여행이 정해지고 나서 어디를 갈지, 무엇을 먹을지에만 정신이 팔려 있지는 않으신가요? 하지만 인기 있는 장소나 맛집 만큼이나 중요한 것이 바로 날씨입니다.\n\n남북으로 길고 바다로 둘러싸여 있으며 산도 많은 규슈는 지역에 따라 기후가 크게 달라집니다. 이번 기사에서는 날씨를 현마다 해설하는 것 외에 계절마다 어울리는 복장이나 인기의 행사를 소개합니다.\n\n일본의 남서부에 위치하여 온난하다고 알려진 규슈도 북부에는 동서로, 중남부에는 남북으로 산맥이 뻗어있기 때문에 지역에 따라 기후가 달라집니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195617.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195619.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195620.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195621.webp"]'::jsonb, E'2024-12-15'::timestamptz, null),
(E'https://matcha-jp.com/ko/23496', E'ko', 42, E'【2025】나가사키 랜턴 페스티벌이 1/29~2/12에 개최! 볼거리와 즐기는 방법을 철저하게 해설!', E'이 기사에서는, 나가사키 랜턴 페스티벌에 가고 싶은 사람을 향해, 나가사키 랜턴 페스티벌의 볼거리나 즐기는 방법, 2025년의 일정을 해설합니다. 액세스나 주차장 정보에 대해서도 해설하고 있으므로, 꼭 참고로 해 봐!\n\n2025년은 1월 29일부터 2월 12일까지 약 15,000개의 등불과 화려한 오브제 등 다양한 전시를 즐길 수 있다. 또한, 전시뿐만 아니라 중국의 역사를 느낄 수 있는 \'황제의 퍼레이드\'와 용춤, 이호 연주 등의 \'무대 이벤트\' 등 매력 넘치는 이벤트가 준비되어 있다.\n\n이번 기사에서는 나가사키 랜턴 페스티벌의 볼거리와 즐기는 방법, 교통편, 주차장 정보 등을 소개하니 꼭 끝까지 읽어보시기 바랍니다!\n\n지금부터 2025 나가사키 랜턴 페스티벌의 볼거리를 엄선하여 소개하겠습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217865.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217859.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217860.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/05-217862.webp"]'::jsonb, E'2025-01-20'::timestamptz, null),
(E'https://matcha-jp.com/ko/5858', E'ko', 42, E'나가사키의 밤을 즐겨보자! 추천 야경지와 일품요리', E'나가사키의 밤거리에서 꼭 즐겨보고 싶은 것이 바로 야경과 나가사키의 음식이죠. 이나사야마, 나베칸무리야마 공원, "데지마 워프"에서 아름다운 야경을 감상한 뒤에 현지 식당에서 맛있는 요리를 맛봅시다. 터키라이스와 나가사키 짬뽕, 나가사키의 해산물 요리, 나가사키 오뎅에 대한 역사와 맛집을 소개합니다!\n\n규슈 지방(九州地方)에 있는 나가사키시(長崎市)는 에도시대(江戸時代) 때 유일하게 해외에 개항한 항구도시로 발전한 도시예요. 유럽과 중국의 영향을 받아 독자적인 문화가 꽃피었고, 일본에서도 이국적인 정서를 느낄 수 있는 장소로서 인기를 끌고 있지요.\n\n오페라 "나비부인"이 탄생한 배경이라고 여겨지는 "구라바 저택(グラバー住宅)" 및 일본에서 가장 오래된 고딕 양식 천주교회인 "오우라 천주당(大浦天主堂)"이 있어요. 16세기에 포르투갈에서 전해진 과자 "카스텔라" 등 외국의 분위기를 느낄 수 있는 건물과 식문화가 지금도 남아 있어, 이곳을 찾는 사람들을 사로잡고 있답니다.\n\n낮 동안 관광지를 둘러본 다음, 나가사키의 밤거리에서 꼭 추천하고 싶은 곳이 있어요. 그곳은 바로 홍콩, 모나코와 함께 세계 신 3대 야경으로 선정된 아름다운 야경지예요.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50518.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50519.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50520.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50521.webp"]'::jsonb, E'2018-04-03'::timestamptz, E'나가사키시'),
(E'https://matcha-jp.com/ko/3323', E'ko', 42, E'나가사키 100% 가이드. 관광 스폿 21선, 구역 가이드, 음식, 이동수단 등', E'일본이면서 이국정서가 흐르는 마을 나가사키. 그런 나가사키의 매력을 풀어드릴게요! 나가사키로 가는 방법과 나가사키의 교통 사정, 구역 가이드, 추천 관광 스폿 21선, 모델 루트 등, 나가사키를 관광할 때 빼놓을 수 없는 정보를 정리했습니다.\n\n큐슈 지방(九州地方) 북서쪽에 위치한 나가사키현 나가사키시(長崎県長崎市)는 일본이면서도 이국정서가 흐르는 매력적인 지역이에요.\n\n그 옛날 에도 시대(江戸時代), 포르투갈에서 철포(鉄砲)와 기독교가 카고시마 타네가 섬(種子島)에 전래되었답니다. 그에 뒤따라 나가사키도 서양과의 교역 항구로 발전했습니다. 그리고 쇄국 정책이 펼쳐지던 와중에도 인공 섬 「데지마(出島)」를 통해 국내에서 유일하게 네덜란드, 중국과 등과 교역을 계속하며 번영했습니다. 덕분에 서양과 기독교의 영향을 크게 받았던 흔적이 남아 있답니다. 또, 나가사키는 원폭 투하를 당했던 마을로 알려져서 평화를 기원하는 평화 공원에 방문하는 사람들이 끊이지를 않는답니다.\n\n나가사키에는 그런 역사와 관련된 관광 스폿이 잔뜩 있어요. 계절에 따른 이벤트, 이문화적인 분위기, 맛있는 음식 등을 찾아 많은 사람들이 방문한답니다. 이 기사에서는, 역사를 만나는 동시에 보고, 먹고, 느끼며 즐거운 나가사키를 소개해 드릴게요.', E'["https://resources.matcha-jp.com/resize/720x2000/2016/11/11-8891.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/15-125679.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/15-125680.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/15-125696.webp"]'::jsonb, E'2017-04-04'::timestamptz, E'나가사키시'),
(E'https://matcha-jp.com/ko/1806', E'ko', 43, E'【쿠마모토 지진】방일 여행객을 위한 재해 정보 모음', E'2016년 4월 15일, 일본의 쿠마모토현에서, 최대 진도7인 지진이 일어났습니다. 현재, 대한민국 외교부에서는 후쿠오카 총영사관 홈페이지를 통해 귀국 교통 수단에 대한 안내를 하고 있습니다.\n\n후쿠오카 총영사관 홈페이지를 통해 귀국 교통 수단에 대한 안내를 하고 있습니다.>\n\n2016년 4월 15일, 일본 큐슈 지방(큐슈 지방)의 쿠마모토(熊本)현에서, 최대 진도7인 지진이 일어났습니다. 현재(4/19)도 대규모 여진이 반복되고 있어 끝을 예상조차 할 수 없는 상황이 이어지고 있습니다.\n\n본 기사에서는, 쿠마모토현과 큐슈 지방을 여행중인 방일 여행객을 위해 이번 지진에 관한 재해 정보가 올라오는 다국어 정보 소스를 정리했습니다.', E'["https://resources.matcha-jp.com/old_thumbnails/720x2000/1806.webp"]'::jsonb, E'2016-04-20'::timestamptz, E'구마모토시'),
(E'https://matcha-jp.com/ko/20733', E'ko', 43, E'아마쿠사의 관광 추천 장소 5곳! 1박 2일 추천 코스도 소개', E'아마쿠사 관광을 고민하고 계신 분들을 대상으로 아마쿠사의 대표적인 맛집과 역사적인 마을 등 추천 관광 명소를 자세히 소개합니다. 또한 1박 2일의 추천 코스와 추천 호텔을 소개하며 아마쿠사에 대한 다양한 의문에도 답해드립니다.\n\n아마쿠사는 아름다운 섬들로 이루어져 있으며 풍부한 자연과 역사적 매력을 지닌 지역입니다. 이번 기사에서는 돌고래 관찰과 신선한 해산물을 즐길 수 있는 맛집, 역사가 살아 숨쉬는 마을 등 아마쿠사의 관광지를 자세히 소개합니다.\n\n또한 아마쿠사의 매력을 마음껏 즐길 수 있는 1박 2일의 추천 코스와 추천 호텔도 소개하니 계획을 세울 때 참고해보세요.\n\n아마쿠사는 구마모토현의 남서부에 위치하고 있으며 약 120개의 섬으로 이루어져 있습니다. 규슈 본토와는 아마쿠사 고쿄(오교)로 연결되어 있으며 풍부한 자연환경과 아름다운 바다가 특징입니다. 또한 새우나 성게 등의 신선한 해산물은 관광 등으로 방문하는 사람들의 미각을 사로잡습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189751.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189750.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189752.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189753.webp"]'::jsonb, E'2025-01-27'::timestamptz, null),
(E'https://matcha-jp.com/ko/21914', E'ko', 43, E'구마모토의 날씨 완벽 분석! 계절별 특징과 베스트 관광지', E'구마모토의 계절별 날씨 특징과 기온, 최적의 복장에 대해 소개합니다. 계절에 맞는 옷차림은 쾌적한 구마모토 관광에 앞서 무엇보다 중요합니다. 구마모토에 간다면 꼭 방문하고 싶은 관광 추천 명소도 함께 소개하니 참고하여 행선지를 결정해보세요.\n\n이번 기사에서는 구마모토의 사계절 날씨 특징과 최적의 복장, 관광 추천 명소 등을 소개합니다. 여행지의 날씨와 기온을 참고하여 여행 준비에 활용해보세요.\n\n동쪽에는 해발 1,000m를 넘는 규슈 산지, 서쪽에는 동중국해와 아리아케해가 있는 구마모토현은 지역에 따라 기후 특성이 크게 달라집니다. 산측에 위치한 아소 지방은 겨울의 추위가 심한 반면, 서쪽의 아마쿠사·아시키타 지방은 겨울에도 비교적 온난합니다.\n\n구마모토현은 동중국해에서 유입되는 따뜻하고 습한 공기의 영향을 받아 호우·집중 호우 등이 발생하기 쉬운 지역입니다. 특히 미야자키현과 가고시마현에 인접한 산 깊은 규슈 산지 부근에서는 연간 강수량이 도쿄의 2배 가까운 3,200mm에 이를 정도입니다. 그 밖의 평야 지역에서도 연 강수량은 2,000mm로 다소 많습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/03-200228.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/03-200229.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/03-200246.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/03-200231.webp"]'::jsonb, E'2024-12-15'::timestamptz, E'아소'),
(E'https://matcha-jp.com/ko/2046', E'ko', 44, E'변하지 않는 아름다움. 오이타현 「온타야키(小鹿田焼)」', E'에도시대부터 풍족한 서민 문화가 자리매김한 오이타 현 히타시(大分県日田市).그 북부에는 후쿠오카 현과 오이타 현을 나누는 산이 우뚝 솟아 있답니다. 그런 산속에는 300년 이상 전부터 전통적인 도자기를 만들고 있는 집락(集落)이 있답니다. 통칭 온타야키(小鹿田焼)의 마을이에요!\n\n에도시대(江戸時代)부터 풍족한 서민 문화가 자리매김한 오이타 현 히타시(大分県日田市).\n\n그 북부에는 후쿠오카 현과 오이타 현을 나누는 산이 우뚝 솟아 있답니다. 그런 산속에는 300년 이상 전부터 전통적인 도자기를 만들고 있는 집락(集落)이 있답니다. 통칭 온타야키(小鹿田焼)의 마을이에요!\n\n산간의 자그마한 공간에서 서로의 어깨를 감싸듯이 공방들이 나란히 서 있습니다. 온타 지구에 있는 카마모토(窯元/도자기 공방)는 약 10채로, 전통적인 작법을 지키기 위해 이 이상 늘리지 않고 부모가 자식에게 대대손손 도자기 만드는 기술을 계승하고 있다고 해요.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/03/30-124709.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123122.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123130.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/21-123123.webp"]'::jsonb, E'2016-07-29'::timestamptz, E'히타시'),
(E'https://matcha-jp.com/ko/4391', E'ko', 44, E'[오이타현] 유후인 온천 ~가는 방법・당일 입욕・추천 료칸 등~', E'오이타현에 있는 유후인 온천은 가족과 여성들에게 인기가 많은 온천으로 웅장한 유후다케를 바라보며 즐기는 노천탕은 탁 트인 개방감을 자랑합니다! 가는 방법과 당일 입욕 장소, 추천 료칸, 즐길 만한 포인트를 소개합니다.\n\n규슈 지방 오이타현에 있는 유후인 온천은 가족 단위 손님이나 여성들에게 특히 인기가 많은 온천입니다. 웅장한 유후다케를 바라보며 즐기는 노천탕은 탁 트인 개방감으로 가득합니다! 평화로운 온천 거리에서 식사와 디저트를 즐기거나 잡화를 구입하거나 미술관을 구경하는 등 여유로운 한때를 보내실 수 있습니다.\n\n유후인 온천의 효능과 가는 방법, 추천하는 온천 료칸 등을 모두 정리했습니다.\n\n유후인 온천의 수질은 무색 투명의 부드러운 단순 온천으로 스트레스 해소, 피로 회복 등의 효과를 기대해 볼 수 있습니다. 일부에는 천연 보습 성분이 풍부하게 함유된 아오유(青湯)도 있어 여성들에게 큰 인기를 끌고 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/05/25-27358.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/31-27751.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/09-28405.webp","https://resources.matcha-jp.com/resize/720x2000/2017/05/23-27058.webp"]'::jsonb, E'2023-06-20'::timestamptz, E'유후인 온천'),
(E'https://matcha-jp.com/ko/7356', E'ko', 44, E'하카타에서 당일치기로! 유후인에서 하고 싶은 10가지-긴린코, 와규, 미술관, 온천', E'하카타에서 당일치기 코스로 부담없이 즐길 수 있는 유후인 여행을 소개합니다. 유후인에는 온천 이외에도 매력이 가득! 유후인역 주변부터 유후인역 기슭에 있는 호수 긴린코까지, 그 안에서 즐기는 귀엽고 맛있는 아트 여행은 어떤가요?\n\n유후다케(유후만)를 중심으로 한 아름다운 전원 풍경이 펼쳐져 있고 풍부한 온천량으로도 유명한 오이타현 유후시에 있는 온천지, 유후인(※1)은 일본에서도 유명한 온천지입니다.\n\n후쿠오카시의 중심 하카타에서 당일치기로 충분히 갈 수 있는 거리, 온천 이외에도 새로운 명소가 늘어나며 다시 한번 주목받는 관광지가 되고 있습니다. 그 중에서도 추천 맛집, 카페, 미술관 등 유후인에 가면 하고 싶은 일을 10가지 항목으로 엄선했습니다.\n\n※1: 유후인에는, 유후인(由布院)과 유후인(湯布院) 총 두 가지의 지명 표기 방식이 있습니다. 본래 유후인(由布院)이라는 지명이 먼저 있었고 유후인초와 유노히라초가 합병하면서 유후인이라는 지명이 생겨났습니다. 역 등의 표기는 유후인(由布院)으로 되어 있으며 해당 기사에서도 고유명사인 경우를 제외하고 유후인(由布院)으로 표기합니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/25-76070.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75877.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75878.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75879.webp"]'::jsonb, E'2023-10-17'::timestamptz, E'유후시'),
(E'https://matcha-jp.com/ko/6263', E'ko', 45, E'미야자키 (宮崎)・타카치호 (高千穂)에서 꼭 해봐야할 여섯가지', E'미야자키현의 북단에 위치하는「타카치호」. 작은 마을이면서도 타카치호 협곡으로 대표되는 웅대한 자연과 다양한 신화와 함께 역사가 숨쉬고 있어 많은 관광객이 찾아옵니다. 이번에는 그러한 타카치호의 매력을 백배 즐기기 위해 꼭 방문해보고 싶은 장소를 소개합니다.\n\n미야자키현 (宮崎県)・타카치호 (高千穂) 는, 일본의 기원 및 건국 이야기를 다룬「일본신화 (日本神話)」(※1) 과 관계깊은 땅으로써 알려져있습니다. 그 전설은 이 지역의 웅대한 자연을 배경으로 하고 있어 현재도 타카치호에는 다양한 전설의 무대가 된 장소가 남아 있습니다.\n\n그래서 이번에는「자연」과「역사」를 중심으로 타카치호의 매력을 체험할 수 있는 스폿들을 전해드립니다.\n\n※1：일본신화……역사서『고사기 (古事記)』『일본서기 (日本書紀)』등에 기재되어 있는 일본의 쿠니 (옛 지역 국가)의 성립이나 천황가의 역사를 기술한 이야기. 신과 사람의 관계나 사람들의 삶이 생생하게 묘사되어있다.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/28-57269.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/29-57280.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/29-57281.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/28-57274.webp"]'::jsonb, E'2019-02-18'::timestamptz, E'타카치호정'),
(E'https://matcha-jp.com/ko/3953', E'ko', 46, E'카고시마 최남단!! 아름다운 해변이 펼쳐진 낙원 「요론 섬(与論島)」의 매력 8선', E'요론 섬은 카고시마 현 최남단에 있는 섬으로, 카고시마 본토보다 오키나와 현에 가까운 남쪽 섬이에요. 아름다운 해변과 파란 하늘은 물론 카고시마와도 오키나와와도 다른 요론 섬의 독자적인 문화가 많은 여행자의 마음을 빼앗는답니다. 그런 요론 섬에서 꼭 가야하는 장소와 체험해야 하는 것들을 소개해 드릴게요!\n\n요론 섬(与論島)은 카고시마 현에서도 최남단에 있는 섬이에요. 섬에서 남쪽으로 22km를 가면 오키나와 본 섬이 있어 카고시마 현이면서도 오키나와의 문화를 느낄 수 있답니다. 인구는 약 6,000인이지만 남국 기후 속에서 생활하는 사람들답게 매우 따듯하고 친근한 사람이 많아요.\n\n그러 요론 섬의 관광 스폿과 요론 섬에 뿌리 내린 문화를 소개해 드릴게요!\n\n오오카네쿠(大金久) 해안은 요론 섬 최대의 바닷가로, 해수욕 시즌이 되면 관광객으로 떠들썩해진답니다. 요론 섬을 방문한 거의 모든 관광객들이 반드시 들르는 장소로, 글래스보드와 스노켈 같은 액티비티도 충실하며 매점도 있어요. 끝없이 이어진 하얀 모래사장을 보며 느긋하게 독서를 해도 좋겠지요.', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/27-19952.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/27-19953.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/27-19955.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/08-18239.webp"]'::jsonb, E'2017-03-06'::timestamptz, E'요로 이아'),
(E'https://matcha-jp.com/ko/24933', E'ko', 46, E'【활화산】사쿠라지마 관광 가이드! 추천 시즌 & 분화 정보, 페리 이용 방법도 소개', E'활화산 사쿠라지마의 매력을 철저 해설! 사쿠라지마의 절경 명소, 베스트 시즌, 분화 실시간 정보 및 여행 전 알아두어야 할 주의사항(항공편, 페리)도 소개. 웅장한 사쿠라지마로 역동적인 자연을 만끽하는 여행을 떠나보세요.\n\n연평균 약 200회나 분화를 반복하는 활발한 화산임에도 불구하고, 약 4,000명의 사람들이 이곳에서 살아가고 있습니다. 그 역동적인 경관은 자연의 강인함을 온몸으로 느끼게 해줍니다. 시시각각 표정을 바꾸는 산의 모습, 솟아오르는 흰 연기, 그리고 가고시마만(긴코만)과의 대비는 그야말로 숨 막히는 절경입니다.\n\n이 기사에서는 사쿠라지마의 매력적인 절경 명소와 추천 베스트 시즌 외에도 화산 분화가 관광에 미치는 영향, 그리고 실시간으로 화산의 모습을 확인할 수 있는 사쿠라지마 라이브 카메라 정보 등을 자세히 알려드립니다.\n\n【중요】2025년 5월 15일 이후 사쿠라지마의 연속 분화로 인해 가고시마 공항 출발/도착 항공편 중 많은 결항이 발생했습니다. 최신 항공편 정보는 각 항공사 공식 홈페이지에서, 사쿠라지마 관광 정보는 \'모두의 사쿠라지마\' 공식 홈페이지에서 확인하시는 것을 추천합니다. (2025년 5월 22일 기준)', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234253.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234254.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234255.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/22-234256.webp"]'::jsonb, E'2025-05-22'::timestamptz, E'사쿠라지마'),
(E'https://matcha-jp.com/ko/6679', E'ko', 46, E'가고시마 (鹿児島) 를 대표하는 관광지！「센간엔 (仙巌園)」을 즐기는 여덟가지 포인트', E'가고시마를 대표하는 정원「센간엔 (仙巌園)」. 사쿠라지마와의 절경 스폿이나 다이묘가 생활했던 저택, 가고시마의 역사・문화를 체험할 수 있는 스폿 등 볼거리가 가득합니다. 드라마의 촬영지로도 활용되어, 점점 더 주목받는 센간엔의 매력을 소개합니다！\n\n가고시마를 대표하는 관광지라 하면 「센간엔 [仙巌園(せんがんえん)]」. 50,000제곱미터나 뻗어있는 광대한 정원입니다.\n\n가고시마 (鹿児島) 의 중심지로부터는 직통 버스로 약 40분정도. 연일 많은 사람들로 붐빕니다.\n\n센간엔은 그 아름다운 정원도 널리 알려져 있지만 그 외에도 다이묘 (大名) 의 삶을 엿볼 수 있는 고덴 (御殿)이나 전통공예의 제작 풍경을 바로 옆에서 볼 수 있는 공장 등, 천천히 시간을 들여 돌아보고 싶은 스폿이 많습니다. 2018년에는 일본의 대하드라마(※1)『세고동 [西郷(せご)どん]』의 촬영지로 선정되어 더욱 주목받고 있습니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65761.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65754.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/09-69126.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65759.webp"]'::jsonb, E'2019-02-13'::timestamptz, E'사쿠라지마'),
(E'https://matcha-jp.com/ko/6311', E'ko', 47, E'"호시노야 다케토미지마" - 오키나와에서 섬생활을 즐겨 보자!', E'"호시노야 다케토미지마"는 오키나와의 다케토미지마(인구 약 350명)에 있는 리조트 시설로, 전통과 자연이 살아 숨 쉬는 평화로우면서도 마음이 설레는 시설이에요.\n\n휴가하면, 조용하고 아름다운 해변에서 파란 바다를 바라보며 여유로운 시간을 보내는 그런 이미지를 갖고 있지는 않나요? "호시노야 다케토미지마(星のや竹富島)"에 며칠간 체류한다면 그런 꿈을 이룰 수 있어요.\n\n"호시노야 다케토미지마(星のや竹富島)"는 오키나와(沖縄)의 아에야마 제도(八重山諸島)에 속하는 다케토미 섬(竹富島)에 있어요.\n\n다케토미 섬(竹富島)은 인구 350명 정도의 조용한 섬으로, 고즈넉한 장소를 좋아하는 분에게는 최고의 여행지라 할 수 있어요.', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/02-59744.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/21-58880.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/21-58881.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/18-58641.webp"]'::jsonb, E'2019-02-22'::timestamptz, E'야에야마 제도'),
(E'https://matcha-jp.com/ko/2940', E'ko', 47, E'일본의 리조트지 「오키나와」를 여행하기 위한 완전 가이드', E'오키나와란 오키나와 본섬과 160여 개의 이도를 포함한 일본 최남단의 현. 온난한 기후로 풍부한 자연, 하얀 모래사장을 가진 해변과 독특한 식문화를 즐길 수 있습니다. 타이완이나 서울에서 직항이 있어 국내외에서 많은 관광객이 오는 일본의 리조트 지랍니다. 그런 오키나와로 가는 방법, 관광지, 추천 음식, 호텔 정보 등, 오키나와 여행 시에 필요한 정보를 모아보았습니다.\n\n오키나와 현은, 오키나와 본섬과 160개의 이도(離島)를 포함한 일본 최남단의 현이에요. 오키나와 본 섬과 그 외 이도에는 하얀 모래사장의 해변이 대부분. 매년 700만 명 이상의 관광객이 찾아오는 아시아를 대표하는 리조트지입니다.\n\n도쿄에서 나하까지의 거리는 약 2,100km. 북경에서는 1,900km, 서울에서는 1,300km로 어느 곳에서든 비행기 직항 편으로 2, 3시간이면 도착합니다. 대만에서는 750km 정도이고, 직항편으로 1시간 30분이면 갈 수 있는, 아시아 사람에게 정말 가까운 외국 관광지라고도 할 수 있을 것 같아요.\n\n오키나와는 온대에 있는 혼슈(本州:일본 열도의 주가 되는 가장 큰 섬)와는 달리, 아열대에 있어요. 온난 기후가 특징으로 파인애플과 같은 열대 과일과 사탕수수의 산지로도 알려져 있어요.', E'["https://resources.matcha-jp.com/archive_files/jp/2016/01/tokyo_to_nagoya_20160125c.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/30-124772.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/20160930okinawa9.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/30-124773.webp"]'::jsonb, E'2017-09-17'::timestamptz, E'오키나와 본섬'),
(E'https://matcha-jp.com/ko/916', E'ko', 47, E'나하에서 당일치기도 가능! 옛 오키나와가 남아있는 섬 「쿠다카 섬(久高島)」', E'오키나와 본도(本島)의 남쪽에는 예로부터「신의 섬」으로 알려진 섬이 있답니다. 그 섬은 <b>쿠다카 섬(久高島)</b>이라고 합니다.\n\n섬 내에는 높은 건물은 하나도 없고, 있는 그대로의 자연 속에 작은 촌락이 있답니다. 주민들이 쓰는 말은 예로부터 이어진 우치나 구치(ウチナーグチ/※1)로, 모든 사람들에게「안녕하세요(こんにちは)」라고 인사해 주신답니다. 그런 오랜 옛날의 오키나와를 느낄 수 있는 섬입니다.\n\n나하(那覇)에서 차로 약 30분, 사이하노 우타키(斎場御嶽)에 있는 난죠우 시(南城市)로. 거기에서 고속선으로 15분 정도 더 가 봅시다. 둘레는 약 8km, 인구는 200명 남짓. 조용하고 아름다운 쿠다카 섬의 풍경이 눈 앞에 나타납니다.\n\n요즘 들어 파워 스폿으로 알려지기 시작한 쿠다카 섬. 아름다운 자연 속에서 조용하고 여유롭게 시간을 보내기엔 최적인 장소입니다.', E'["https://resources.matcha-jp.com/resize/720x2000/2022/04/25-126008.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/25-126007.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/25-126006.webp","https://resources.matcha-jp.com/resize/720x2000/2022/04/25-126005.webp"]'::jsonb, E'2015-07-05'::timestamptz, E'나하시')
